fn walk(lo:i32,hi:i32)->i32{
        mut visits:=0;mut total:=0
        for i in lo..hi{
            visits=visits+1;if visits>64{return -999}
            if i%2==0{continue};if i>9{break};total=total+i
        }
        return visits*100+total
    }
    fn main(){print(walk(-7,-1));print(walk(-2,3));print(walk(0,17));print(walk(7,7));print(walk(12,3));}

fn walk(n:i32)->i32{
        mut total:=0
        for i in 0..n{
            for j in 0..n{
                if j==2{continue};if j==5{break}
                mut k:=0
                while k<3{k=k+1;if k==2{continue};total=total+i+j+k}
            }
            if i==7{return total}
        }
        return total
    }
