fn arrange(a:&mut []i64){
        for i in 1..a.len{
            value:=a[i];mut j:=i
            while j>0&&a[j-1]>value{a[j]=a[j-1];j=j-1}
            a[j]=value
        }
    }
    fn reflect(a:&mut []i64){
        mut left:=0;mut right:=a.len-1
        while left<right{value:=a[left];a[left]=a[right];a[right]=value;left=left+1;right=right-1}
    }
